css:
body {
	margin: 0;
	font-family: sans-serif;
	color: #22223b;
}

.page {
	padding: 16px;
}

.cards {
	display: flex;
	flex-direction: column;
	gap: 12px;
}

.card {
	padding: 12px;
	background: #f2e9e4;
	border: 1px solid #4a4e69;
}

.note {
	margin-top: 16px;
	font-size: 15px;
}

@media (min-width: 600px) {
	.cards {
		flex-direction: row;
	}

	.card {
		flex: 1;
	}
}

@media (max-width: 399px) {
	.page {
		padding: 8px;
	}
}

@media (400px <= width < 700px) {
	.note {
		font-size: 17px;
		color: #9a031e;
	}
}
